/* Local POC login only. Published demo credentials and browser session are not production authentication. */
(function(root){'use strict';
const SESSION='training-tracker-session-v1',DATA='training-tracker-review-v1',password='Demo@123',accounts=[
{id:'A1',name:'Sample Central Admin',role:'Schoolnet Admin'},
{id:'A2',name:'Sample ERNET Admin',role:'ERNET Admin'},
{id:'A3',name:'Sample State Admin',role:'State Admin'},
{id:'A4',name:'Sample School Admin',role:'School Admin'},
{id:'A5',name:'Sample Trainer',role:'Trainer'},
{id:'A6',name:'Sample Trainee',role:'Trainee'}];
const pages=['index.html','dashboard.html','projects.html','training-plans.html','batches.html','trainees.html','registration.html','resources.html','content-library.html','attendance.html','assessments.html','completion.html','certificates.html','masters.html','reports.html','users.html','audit.html','rules-decisions.html'];
function users(){try{let d=JSON.parse(root.localStorage.getItem(DATA));return Array.isArray(d?.users)?d.users:accounts}catch{return accounts}}
function session(){try{let s=JSON.parse(root.sessionStorage.getItem(SESSION));return s&&['login','demo'].includes(s.mode)&&users().some(u=>u.id===s.userId)?s:null}catch{return null}}
function set(mode,userId){if(!users().some(u=>u.id===userId))throw Error('Select an available demo user.');root.sessionStorage.removeItem('reviewBatch');root.sessionStorage.setItem('reviewPersona',userId);root.sessionStorage.setItem(SESSION,JSON.stringify({mode,userId}));return session()}
const CREDENTIALS='training-tracker-demo-passwords-v1',OTP_MS=5*60*1000;let resetChallenge=null;
function credentialMap(){try{return JSON.parse(root.localStorage.getItem(CREDENTIALS)||'{}')}catch{return {}}}
function currentPassword(id){return credentialMap()[id]||password}
function resetAccount(mobile){if(!/^\d{10}$/.test(String(mobile||'')))return null;let d;try{d=JSON.parse(root.localStorage.getItem(DATA)||'{}')}catch{return null}let matches=users().filter(u=>String(u.mobile||(u.registeredMobile?u.id:'')||(d.trainees||[]).find(t=>t.id===u.trainee)?.mobile||'')===mobile);return matches.length===1?matches[0]:null}
function passwordErrors(secret,u){let e=[];if(secret.length<8)e.push('Use at least 8 characters.');if(!/[A-Z]/.test(secret))e.push('Include an uppercase letter (A–Z).');if(!/[a-z]/.test(secret))e.push('Include a lowercase letter (a–z).');if(!/[0-9]/.test(secret))e.push('Include a number (0–9).');if(!/[^A-Za-z0-9\s]/.test(secret))e.push('Include a special character.');if(/\s/.test(secret))e.push('Do not use spaces or other whitespace.');if(u&&secret===currentPassword(u.id))e.push('Your new password must differ from your previous password.');let d;try{d=JSON.parse(root.localStorage.getItem(DATA)||'{}')}catch{d={}}let t=(d.trainees||[]).find(t=>t.id===u?.trainee)||{},tokens=[u?.id,u?.mobile,t.mobile,u?.email,t.email,...String(u?.name||t.name||'').split(/\s+/),String(u?.email||t.email||'').split('@')[0],u?.dob,t.dob,u?.dateOfBirth,t.dateOfBirth].filter(v=>v&&String(v).length>=3);if(tokens.some(v=>secret.toLowerCase().includes(String(v).toLowerCase()))||(u?.id&&secret.toLowerCase().includes(u.id.toLowerCase())))e.push('Avoid your name, username, mobile number, email address or recorded date of birth.');return e}
function requestResetOTP(mobile){resetChallenge=null;let u=resetAccount(mobile);if(!u)return {ok:false,message:'Enter the 10-digit mobile number registered to an available account.'};resetChallenge={userId:u.id,mobile,otp:'123456',expires:Date.now()+OTP_MS};return {ok:true,otp:'123456',expires:resetChallenge.expires,message:'SIMULATED OTP: 123456. No SMS was sent. Valid for 5 minutes (POC assumption).'}}
function resetRemaining(){return resetChallenge?Math.max(0,Math.ceil((resetChallenge.expires-Date.now())/1000)):0}
function resetPassword(mobile,otp,secret,confirm){let u=resetAccount(mobile);if(!resetChallenge||!u||u.id!==resetChallenge.userId||mobile!==resetChallenge.mobile)return {ok:false,errors:['Request an OTP for your registered mobile number.']};if(Date.now()>=resetChallenge.expires){resetChallenge=null;return {ok:false,errors:['OTP has expired. Request a new OTP.']}}if(otp!==resetChallenge.otp)return {ok:false,errors:['Enter the correct OTP.']};let errors=passwordErrors(secret,u);if(secret!==confirm)errors.push('Passwords do not match.');if(errors.length)return {ok:false,errors};try{let credentials=credentialMap();credentials[u.id]=secret;root.localStorage.setItem(CREDENTIALS,JSON.stringify(credentials));resetChallenge=null;logout();return {ok:true,userId:u.id,message:'Password set successfully. Log in with your User ID and new password.'}}catch{return {ok:false,errors:['Password could not be saved. Enable browser storage and try again.']}}}

function login(id,secret){id=String(id||'').trim().toUpperCase();const defaultAdmin=id==='ADMIN';if(defaultAdmin)id='A1';if(!users().some(u=>u.id===id&&(accounts.some(a=>a.id===id)||(u.registeredMobile===true&&u.role==='Trainee'&&/^\d{10}$/.test(id))))||secret!==(defaultAdmin?'admin@123':currentPassword(id)))return {ok:false,message:'Invalid User ID or password.'};try{return {ok:true,session:set('login',id)}}catch{return {ok:false,message:'Browser session storage is unavailable. Enable storage and try again.'}}}
function logout(){for(let key of [SESSION,'reviewPersona','reviewBatch'])root.sessionStorage.removeItem(key)}
function safeNext(raw){let base=String(raw||'').split('?')[0];return pages.includes(base)&&/^[a-z-]+\.html(?:\?batch=[A-Za-z0-9_%.-]+)?$/.test(String(raw))?raw:'index.html'}
function allowed(role,page){if(api.publicGuest)return ['registration','reset'].includes(page);if(role==='Schoolnet Admin')return true;if(role==='ERNET Admin'&&['registration','certificates','masters','plans','completion'].includes(page))return false;if(['users','audit','review'].includes(page))return page==='users';if(role==='Trainee')return ['dashboard','projects','plans','batches','registration','resources','content','attendance','assessments','certificates'].includes(page);return true}
const api={requestResetOTP,resetPassword,resetRemaining,passwordErrors,accounts,password,users,session,login,logout,useDemo:id=>set('demo',id),safeNext,allowed,authorized:true,publicGuest:false};root.DemoAuth=api;if(typeof module!=='undefined')module.exports=api;
if(!root.document)return;let page=root.document.body?.dataset.page;
if(root.location.protocol==='file:'){api.authorized=false;root.document.body.innerHTML='<main style="max-width:720px;margin:60px auto;padding:24px;font-family:Arial,sans-serif"><h1>Start Training Tracker</h1><p>This application needs a local web address for login, navigation and file previews.</p><ol><li>Close this tab.</li><li>Open the extracted folder and double-click <strong>Start-Training-Tracker.bat</strong>.</li><li>The login page opens automatically at <strong>http://localhost:8080/login.html</strong>.</li></ol><p>Python 3 must be installed. Keep the launcher window open while using the POC.</p></main>';return;}

if(page==='login'){
 let el=id=>root.document.getElementById(id),params=new URLSearchParams(root.location.search),next=safeNext(params.get('next'));
 el('loginForm').addEventListener('submit',event=>{event.preventDefault();el('loginError').textContent='';let result=login(el('loginId').value,el('loginPassword').value);if(!result.ok){el('loginError').textContent=result.message;el('loginPassword').value='';el('loginPassword').focus();return}root.location.href=next});
 el('togglePassword').addEventListener('click',()=>{let show=el('loginPassword').type==='password';el('loginPassword').type=show?'text':'password';el('togglePassword').textContent=show?'Hide password':'Show password';el('togglePassword').setAttribute('aria-pressed',String(show))});
 el('demoEntry').addEventListener('click',()=>{try{api.useDemo(el('demoRole').value);root.location.href=next}catch(err){el('loginError').textContent=err.message}});
 if(params.get('loggedout'))el('loginStatus').textContent='You have logged out. Sign in to continue.';
}else if(page){let s=session();api.publicGuest=!s&&['registration','reset'].includes(page);if(!s&&!['registration','reset'].includes(page)){api.authorized=false;root.document.documentElement.hidden=true;let file=root.location.pathname.split('/').pop()||'index.html',next=safeNext(file+root.location.search);root.location.replace('login.html?next='+encodeURIComponent(next));}}
if(root.addEventListener&&page!=='login')root.addEventListener('pageshow',event=>{if(!session()&&!['registration','reset'].includes(page))root.location.replace('login.html');else if(event?.persisted)root.location.reload();});
})(typeof window==='undefined'?globalThis:window);
